# Now let's distribute into 17 batches:
# Batches 1 to 16: 30 questions each (15 True, 15 False) -> 16 * 30 = 480 questions
# Batch 17: 20 questions (10 True, 10 False) -> 20 questions
# Total = 500 questions.

batches = []
