    batch_items = []
    for _ in range(t_count):
        batch_items.append((true_pool[true_idx][0], True, true_pool[true_idx][1]))
        true_idx += 1
    for _ in range(f_count):
        batch_items.append((false_pool[false_idx][0], False, false_pool[false_idx][1]))
        false_idx += 1
    batches.append(batch_items)

